// Validate incoming request
const body = $input.first().json.body;

if (!body || !body.url) {
  throw new Error('URL is required in request body');
}

if (!body.userId) {
  throw new Error('userId is required in request body');
}

// Validate URL format
const urlPattern = /^https?:\/\/.+/i;
if (!urlPattern.test(body.url)) {
  throw new Error('Invalid URL format. Must start with http:// or https://');
}

// Return validated data
return {
  url: body.url,
  userId: body.userId,
  requestedAt: new Date().toISOString()
};

// Get all scrapes for rate limiting check
const userId = $input.first().json.userId;
const url = $input.first().json.url;

// We'll fetch scrapes in the next node, just pass data through
return {
  userId: userId,
  url: url,
  timestamp: new Date().toISOString()
};

// Check if under rate limit
const scrapeCount = $input.first().json || 0;
const userId = $('Prepare Rate Check').first().json.userId;
const url = $('Prepare Rate Check').first().json.url;

const underLimit = scrapeCount < 10;

return {
  userId: userId,
  url: url,
  scrapeCount: scrapeCount,
  underLimit: underLimit
};

// Parse the Firecrawl response
const response = $input.first().json;
const data = response.data || response;
const originalUrl = $('Evaluate Limit').first().json.url;
const userId = $('Evaluate Limit').first().json.userId;

// Extract metadata
const metadata = data.metadata || {};
const pageTitle = metadata.title || data.title || 'Untitled';
const description = metadata.description || '';

// Extract headings from markdown
const markdown = data.markdown || '';
const headingRegex = /^(#{1,6})\s+(.+)$/gm;
const headings = [];
let match;

while ((match = headingRegex.exec(markdown)) !== null) {
  headings.push({
    level: match[1].length,
    text: match[2].trim(),
    type: `h${match[1].length}`
  });
}

// Extract links
const links = data.links || [];
let processedLinks = [];
try {
  const urlObj = new URL(originalUrl);
  processedLinks = links.map(link => {
    const isInternal = link.startsWith('/') || link.includes(urlObj.hostname);
    return {
      href: link,
      text: link,
      isInternal: isInternal,
      isExternal: !isInternal
    };
  });
} catch (e) {
  processedLinks = links.map(link => ({ href: link, text: link, isInternal: false, isExternal: true }));
}

// Extract text content for word count
const textContent = markdown.replace(/[#*`]/g, '').trim();
const wordCount = textContent.split(/\s+/).filter(w => w.length > 0).length;

// Return structured data
return {
  url: originalUrl,
  userId: userId,
  title: pageTitle,
  description: description,
  headings: headings,
  links: processedLinks,
  rawMarkdown: markdown.substring(0, 5000), // Limit size
  metadata: {
    wordCount: wordCount,
    headingCount: headings.length,
    linkCount: links.length,
    internalLinkCount: processedLinks.filter(l => l.isInternal).length,
    externalLinkCount: processedLinks.filter(l => l.isExternal).length
  },
  scrapedAt: new Date().toISOString()
};

