// Combine parsed content with AI summary
const parsedData = $('Parse Content').first().json;
const aiResponse = $input.first().json;

let aiSummary = 'Summary generation failed';
try {
  aiSummary = aiResponse.choices[0].message.content || 'No summary available';
} catch (e) {
  console.log('Error extracting AI summary:', e);
}

return {
  ...parsedData,
  aiSummary: aiSummary
};

// Get the scrape_id from the previous insert
const scrapeResponse = $input.first().json;
const scrapeId = Array.isArray(scrapeResponse) ? scrapeResponse[0].id : scrapeResponse.id;
const data = $('Combine Data').first().json;

// Prepare batch insert data for scraped_content table
const contentItems = [];

// Add title
if (data.title) {
  contentItems.push({
    scrape_id: scrapeId,
    content_type: 'title',
    content: data.title,
    context: { description: data.description }
  });
}

// Add headings (limit to 50)
data.headings.slice(0, 50).forEach(heading => {
  contentItems.push({
    scrape_id: scrapeId,
    content_type: 'heading',
    content: heading.text,
    context: { level: heading.level, type: heading.type }
  });
});

// Add links (limit to 100)
data.links.slice(0, 100).forEach(link => {
  contentItems.push({
    scrape_id: scrapeId,
    content_type: 'link',
    content: link.text || link.href,
    context: { 
      href: link.href, 
      isInternal: link.isInternal,
      isExternal: link.isExternal
    }
  });
});

return {
  scrapeId: scrapeId,
  contentItems: contentItems
};

// Prepare success response
const scrapeId = $('Prepare Content Items').first().json.scrapeId;
const originalData = $('Combine Data').first().json;

return {
  success: true,
  message: 'Website scraped successfully',
  data: {
    scrapeId: scrapeId,
    url: originalData.url,
    title: originalData.title,
    summary: originalData.aiSummary,
    stats: originalData.metadata,
    scrapedAt: originalData.scrapedAt,
    contentCounts: {
      headings: originalData.headings.length,
      links: originalData.links.length
    }
  }
};

// Rate limit exceeded response
const scrapeCount = $('Evaluate Limit').first().json.scrapeCount;

return {
  success: false,
  error: 'Rate limit exceeded',
  message: `You have made ${scrapeCount} scrapes in the last hour. Maximum allowed is 10. Please try again later.`,
  retryAfter: '1 hour',
  currentCount: scrapeCount,
  maxAllowed: 10
};
